// Grid.kt - the implementation is file-private, the attorney is the door
private class Grid(private var dirty: Int) {
    fun recalc(i: Int) { dirty = i }
}

internal object GridAttorney {
    private val grids = mutableMapOf<String, Grid>()
    fun refresh(id: String) { grids.getValue(id).recalc(0) }
}
